parameters.command:
sqlite3 -json /data/arabic_dict.db "
SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_bare, e.headword_norm, e.root, e.root_source, e.pos, e.form, e.definitions_text, e.translation_en, e.translation_fr, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.name_en AS dict_name_en, d.source_type AS dict_source_type, d.period AS dict_period, d.author AS dict_author, d.death_year AS dict_death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('دلتا', 'الدلتا') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST, d.name_en;
" > /workspace/q1_headword.json

sqlite3 -json /data/arabic_dict.db "
SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_bare, e.headword_norm, e.root, e.root_source, e.pos, e.form, e.definitions_text, e.translation_en, e.translation_fr, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.name_en AS dict_name_en, d.source_type AS dict_source_type, d.period AS dict_period, d.author AS dict_author, d.death_year AS dict_death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.id IN (SELECT rowid FROM entries_translations_fts WHERE entries_translations_fts MATCH 'translation_en:\"delta\"' ORDER BY bm25(entries_translations_fts, 5.0, 3.0, 1.0) LIMIT 50) ORDER BY d.source_type, d.name_en;
" > /workspace/q2_english_bridge.json

sqlite3 -json /data/arabic_dict.db "
SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_bare, e.headword_norm, e.root, e.root_source, e.pos, e.form, e.definitions_text, e.translation_en, e.translation_fr, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.name_en AS dict_name_en, d.source_type AS dict_source_type, d.period AS dict_period, d.author AS dict_author, d.death_year AS dict_death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.id IN (SELECT rowid FROM entries_fts WHERE entries_fts MATCH '\"مثلثة\" OR \"رواسب\" OR \"طمي\" OR \"مصب\"' ORDER BY bm25(entries_fts, 10.0, 5.0, 5.0, 3.0, 1.0) LIMIT 50) ORDER BY d.source_type, d.name_en;
" > /workspace/q3_fts.json
